(function ($) {
  app.modals.CreateOrEditUserModal = function () {
    var _userService = abp.services.app.user;

    var _modalManager;
    var _$userInformationForm = null;
    var _passwordComplexityHelper = new app.PasswordComplexityHelper();
    var _organizationTree;

    var changeProfilePictureModal = new app.ModalManager({
      viewUrl: abp.appPath + 'App/Profile/ChangePictureModal',
      scriptUrl: abp.appPath + 'view-resources/App/Profile/_ChangePictureModal.js',
      modalClass: 'ChangeProfilePictureModal',
    });

    function _findAssignedRoleNames() {
      var assignedRoleNames = [];

      _modalManager
        .getModal()
        .find('.user-role-checkbox-list input[type=checkbox]')
        .each(function () {
          if ($(this).is(':checked') && !$(this).is(':disabled')) {
            assignedRoleNames.push($(this).attr('name'));
          }
        });

      return assignedRoleNames;
    }

    this.init = function (modalManager) {
      _modalManager = modalManager;

      _organizationTree = new OrganizationTree();
      _organizationTree.init(_modalManager.getModal().find('.organization-tree'), {
        cascadeSelectEnabled: false,
      });

      $.validator.addMethod("customEmail", function (value, element) {
        return this.optional(element) || /^[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.(com|net|org|info|biz|name|vn|edu|gov|mil)$/i.test(value);
      }, "Vui lòng nhập địa chỉ email hợp lệ.");

      _$userInformationForm = _modalManager.getModal().find('form[name=UserInformationsForm]');
      _$userInformationForm.validate({
        validClass: "valid",  // default
        errorClass: "invalid-feedback", // default is "error"
        highlight: function (element, errorClass, validClass) {
          $(element).addClass('is-invalid').removeClass('is-valid');
        },
        unhighlight: function (element, errorClass, validClass) {
          $(element).addClass('is-valid').removeClass('is-invalid');
        },
        rules: {
          EmailAddress: {
            customEmail: true,
          },
          PasswordRepeat: {
            equalTo: "#EditUser_Password"
          }
        },
        messages: {
          EmailAddress: {
            required: 'Email không được để trống',
            customEmail: 'Nhập email hợp lệ'
          },
          Name: {
            required: 'Tên đầy đủ không được để trống',
          },
          UserName: {
            required: 'Tên người dùng không được để trống',
          },
          Password: {
            required: "Mật khẩu không được bỏ trống"
          },
          PasswordRepeat: {
            required: "Xác nhận mật khẩu không được bỏ trống",
            equalTo: "Xác nhận mật khẩu phải trùng với mật khẩu"
          },
        },
        errorPlacement: function (error, element) {
          // Kiểm tra nếu element nằm trong Input Group
          if (element.closest('.input-group').length) {
            error.addClass('text-danger'); // Thêm class Bootstrap cho lỗi màu đỏ
            error.insertAfter(element.closest('.input-group')); // Đặt lỗi sau nhóm input
          } else if (element.closest('.form-check').length) { // Nếu là radio hoặc checkbox
            error.addClass('text-danger');
            error.appendTo(element.closest('.form-check')); // Đặt lỗi sau nhóm radio/checkbox
          } else {
            error.insertAfter(element); // Mặc định cho các trường input khác
          }
        },
        success: function (label, element) {
          $(element).next('.invalid-feedback').remove(); // Xóa thông báo lỗi khi input hợp lệ
        },
        success: function (label, element) {
          $(element).next('.invalid-feedback').remove(); // Remove error message on success
        }
      });


      var passwordInputs = _modalManager.getModal().find('input[name=Password],input[name=PasswordRepeat]');
      var passwordInputGroups = passwordInputs.closest('.user-password');

      _passwordComplexityHelper.setPasswordComplexityRules(passwordInputs, window.passwordComplexitySetting);

      $('#EditUser_SetRandomPassword').change(function () {
        if ($(this).is(':checked')) {
          passwordInputGroups.slideUp('fast');
          if (!_modalManager.getArgs().id) {
            passwordInputs.removeAttr('required');
          }
        } else {
          passwordInputGroups.slideDown('fast');
          if (!_modalManager.getArgs().id) {
            passwordInputs.attr('required', 'required');
          }
        }
      });

      _modalManager
        .getModal()
        .find('.user-role-checkbox-list input[type=checkbox]')
        .change(function () {
          $('#assigned-role-count').text(_findAssignedRoleNames().length);
        });

      _modalManager.getModal().find('[data-bs-toggle=tooltip]').tooltip();

      var GeoUnits = {
        _geoUnitService: abp.services.app.geoUnit,
        _Province: $('#ProvinceSelect'),
        _District: $('#DistrictSelect'),
        _Village: $('#WardSelect'),
        _ProvinceOfCandidate: $('input[name=ProvinceId]'),
        _DistrictOfCandidate: $('input[name=DistrictId]'),
        reloadProvince: function (data) {

          GeoUnits._Province.append($('<option>',
            {
              value: '',
              text: 'Lựa chọn',
              selected: 'true'
            }));

          $.each(data, function (index, item) {
            GeoUnits._Province.append($('<option>',
              {
                value: item.id,
                text: item.displayName,
              }));
          });

          if (GeoUnits._ProvinceOfCandidate.val() != null && GeoUnits._ProvinceOfCandidate.val() != '' && GeoUnits._ProvinceOfCandidate.val() != undefined) {
            GeoUnits._Province.val(GeoUnits._ProvinceOfCandidate.val());
            GeoUnits.getDistrictfromServer(GeoUnits._ProvinceOfCandidate.val());

          }
          GeoUnits.changeProvince();
        },
        changeProvince: function () {
          GeoUnits.getDistrictfromServer(GeoUnits._Province.val())
          GeoUnits._Province.change(function () {
            GeoUnits.getDistrictfromServer($(this).val())
          });
        },
        reloadDistrict: function (data) {
          GeoUnits._District.children().remove();
          $.each(data, function (index, item) {
            GeoUnits._District.append($('<option>',
              {
                value: item.id,
                text: item.displayName,
              }));
          });
          if (GeoUnits._DistrictOfCandidate.val() != null && GeoUnits._DistrictOfCandidate.val() != '' && GeoUnits._DistrictOfCandidate.val() != undefined) {
            GeoUnits._District.val(GeoUnits._DistrictOfCandidate.val());
          }
          GeoUnits.changeDistrict();

        },
        changeDistrict: function () {
          GeoUnits.getVillagefromServer(GeoUnits._District.val())
          GeoUnits._District.change(function () {
            GeoUnits.getVillagefromServer($(this).val())
          });
        },
        reloadVillage: function (data) {
          GeoUnits._Village.children().remove();
          $.each(data, function (index, item) {
            GeoUnits._Village.append($('<option>',
              {
                value: item.id,
                text: item.displayName,
              }));
          });
          if (GeoUnits._VillageOfRecruiter.val() != null && GeoUnits._VillageOfRecruiter.val() != '' && GeoUnits._VillageOfRecruiter.val() != undefined) {
            GeoUnits._Village.val(GeoUnits._VillageOfRecruiter.val());
          }
        },
        getVillagefromServer: function (DistrictId) {
          if (DistrictId == 0 || DistrictId == null || DistrictId == undefined) {
            return;
          }
          GeoUnits._geoUnitService.getChildrenGeoUnit(DistrictId).done(function (result) {
            GeoUnits.reloadVillage(result.items)
          })
        },
        getProvincefromServer: function () {
          GeoUnits._geoUnitService.getChildrenByKeyName({ keyName: 'vi' }).done(function (result) {
            GeoUnits.reloadProvince(result.items)
          })
        },
        getDistrictfromServer: function (ProvinceId) {
          if (ProvinceId == 0 || ProvinceId == null || ProvinceId == undefined) {
            return;
          }
          GeoUnits._geoUnitService.getChildrenGeoUnit(ProvinceId).done(function (result) {
            GeoUnits.reloadDistrict(result.items)
          })
        },
        init: function () {
          GeoUnits.getProvincefromServer();
        }

      }
      GeoUnits.init();

      _modalManager
        .getModal()
        .find('#changeProfilePicture')
        .click(function () {
          changeProfilePictureModal.open({ userId: _modalManager.getModal().find('input[name=Id]').val() });
        });

      changeProfilePictureModal.onClose(function () {
        _modalManager.getModal().find('.user-edit-dialog-profile-image').attr('src', abp.appPath + "Profile/GetProfilePictureByUser?userId=" + _modalManager.getModal().find('input[name=Id]').val())
      });

      _modalManager
        .getModal()
        .find('#SaveAddressBtn')
        .click(function () {
          var user = _$userInformationForm.serializeFormToObject();

          var userAddressPoR = {
            UserId: user.Id,
            GeoUnitId: $("#WardSelect").val(),
            GeoUnitType: 2,
            StreetAddress: $('#AddressPOR').val()
          };

          if ($('#AddressPoRId').val() != '') {
            userAddressPoR.Id = $('#AddressPoRId').val();
          }

          abp.services.app.geoUnit.createOrUpdateUserGeoUnit(userAddressPoR).done(function () {
            abp.notify.info(app.localize('SavedSuccessfully'));
          });
        });

      _modalManager.getModal().find('#SavePersonalBtn').click(function () {
        var user = _$userInformationForm.serializeFormToObject();
        abp.services.app.hrmSettings.updateEnableWeeklyAttendanceMail({
          enable: $('#EnableEmail').is(':checked'),
          userId: user.Id
        }).done(function () {
          abp.notify.info(app.localize('SavedSuccessfully'));
        });
      });
    };

    this.save = function () {
      if (!_$userInformationForm.valid()) {
        return;
      }

      var assignedRoleNames = _findAssignedRoleNames();
      var user = _$userInformationForm.serializeFormToObject();

      if (user.SetRandomPassword) {
        user.Password = null;
      }

      _modalManager.setBusy(true);
      _userService
        .createOrUpdateUser({
          user: user,
          assignedRoleNames: assignedRoleNames,
          sendActivationEmail: user.SendActivationEmail,
          SetRandomPassword: user.SetRandomPassword,
          organizationUnits: _organizationTree.getSelectedOrganizationIds(),
        })
        .done(function () {
          abp.notify.info(app.localize('SavedSuccessfully'));
          _modalManager.close();
          abp.event.trigger('app.createOrEditUserModalSaved');
        })
        .always(function () {
          _modalManager.setBusy(false);
        });
    };
  };
})(jQuery);
